import{_ as a,o as e,c as d,a4 as o}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"mybilibili 数据库层设计取舍","description":"","frontmatter":{"title":"mybilibili 数据库层设计取舍","date":"2026-08-14T00:00:00.000Z"},"headers":[],"relativePath":"posts/mybilibili-数据库层设计取舍.md","filePath":"posts/mybilibili-数据库层设计取舍.md"}'),r={name:"posts/mybilibili-数据库层设计取舍.md"};function i(l,t,s,h,n,c){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="mybilibili-数据库层设计取舍" tabindex="-1">mybilibili 数据库层设计取舍 <a class="header-anchor" href="#mybilibili-数据库层设计取舍" aria-label="Permalink to &quot;mybilibili 数据库层设计取舍&quot;">​</a></h1><blockquote><p>对比 Java 微服务版（MyBatis-Plus + MySQL）vs Go 单体版（<code>database/sql</code> + PostgreSQL）</p></blockquote><h2 id="核心差异" tabindex="-1">核心差异 <a class="header-anchor" href="#核心差异" aria-label="Permalink to &quot;核心差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Java 版</th><th>Go 版</th></tr></thead><tbody><tr><td>数据库</td><td>MySQL 5.7</td><td>PostgreSQL 16</td></tr><tr><td>数据访问层</td><td>MyBatis-Plus (ORM)</td><td><code>database/sql</code> (手写 SQL)</td></tr><tr><td>查询方式</td><td>自动生成 CRUD + 手写 XML</td><td>全部手写 <code>$1</code> 参数化查询</td></tr><tr><td>迁移工具</td><td>Flyway</td><td>无（手动跑 SQL）</td></tr><tr><td>类型安全</td><td>弱（<code>${}</code> 字符串拼接）</td><td>强（只有 <code>$N</code> 参数化）</td></tr></tbody></table><hr><h2 id="安全性对比" tabindex="-1">安全性对比 <a class="header-anchor" href="#安全性对比" aria-label="Permalink to &quot;安全性对比&quot;">​</a></h2><h3 id="go-胜出" tabindex="-1">Go 胜出 <a class="header-anchor" href="#go-胜出" aria-label="Permalink to &quot;Go 胜出&quot;">​</a></h3><p>Go 的 <code>database/sql</code> 只提供 <code>$1</code>、<code>$2</code> 参数化查询这一种传参方式，<strong>没有 <code>${}</code> 拼接的逃生门</strong>。开发者不可能写出 SQL 注入代码。</p><h3 id="java-的隐患" tabindex="-1">Java 的隐患 <a class="header-anchor" href="#java-的隐患" aria-label="Permalink to &quot;Java 的隐患&quot;">​</a></h3><p>MyBatis 提供两种参数绑定：</p><ul><li><code>#{}</code> — 安全，参数化</li><li><code>${}</code> — 危险，裸字符串拼接，用于动态表名/ORDER BY</li></ul><p>Java 版代码里确实存在 <code>${userIds}</code> 拼接写法，虽然量少，但证明了<strong>框架给了刀，就有人会用来砍人</strong>。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p><strong>Go 安全是因为没给你不安全的选项，不是因为它设计得更好。</strong> 就像没钥匙的房子不会遭贼——安全是靠限制换来的，不是靠设计。</p><hr><h2 id="工程效率对比" tabindex="-1">工程效率对比 <a class="header-anchor" href="#工程效率对比" aria-label="Permalink to &quot;工程效率对比&quot;">​</a></h2><h3 id="mybatis-plus-的优势" tabindex="-1">MyBatis-Plus 的优势 <a class="header-anchor" href="#mybatis-plus-的优势" aria-label="Permalink to &quot;MyBatis-Plus 的优势&quot;">​</a></h3><ol><li><strong>自动生成 CRUD</strong>：<code>insert(T)</code>、<code>updateById(T)</code>、<code>selectList(Wrapper)</code> 零代码</li><li><strong>Lambda 查询构造器</strong>：<code>lambdaQuery().eq(User::getName, &quot;test&quot;).list()</code></li><li><strong>分页插件</strong>：一行代码搞定分页</li><li><strong>代码生成器</strong>：表结构 → Entity/Mapper/Service/Controller 全自动</li><li><strong>XML 集中管理</strong>：复杂 SQL 统一在 XML 里，DBA 友好</li></ol><h3 id="go-database-sql-的代价" tabindex="-1">Go <code>database/sql</code> 的代价 <a class="header-anchor" href="#go-database-sql-的代价" aria-label="Permalink to &quot;Go `database/sql` 的代价&quot;">​</a></h3><ol><li><strong>模板代码多</strong>：每个查询都要写 <code>rows.Scan(&amp;a, &amp;b, &amp;c)</code></li><li><strong>无自动映射</strong>：struct 字段和 SQL 列必须手动对应</li><li><strong>无迁移工具</strong>：当前 SQL 文件需要手动执行</li><li><strong>分页手写</strong>：<code>LIMIT $1 OFFSET $2</code> 每页都要写</li></ol><h3 id="量化对比-估算" tabindex="-1">量化对比（估算） <a class="header-anchor" href="#量化对比-估算" aria-label="Permalink to &quot;量化对比（估算）&quot;">​</a></h3><p>对一个典型的 CRUD 业务（5 张表，每表 10 个查询）：</p><table tabindex="0"><thead><tr><th>活动</th><th>MyBatis-Plus</th><th>Go <code>database/sql</code></th></tr></thead><tbody><tr><td>建表 → 跑起来</td><td>30 分钟（代码生成器）</td><td>2 小时（手写全部）</td></tr><tr><td>加一个字段</td><td>5 分钟（改 Entity + XML）</td><td>5 分钟（改 SQL + Scan）</td></tr><tr><td>排查线上 SQL 问题</td><td>快（XML 集中管理）</td><td>中（SQL 散在 repository）</td></tr><tr><td>新人上手</td><td>慢（要学 MyBatis 概念）</td><td>快（就是 SQL）</td></tr></tbody></table><hr><h2 id="为什么-java-版用-mybatis-plus" tabindex="-1">为什么 Java 版用 MyBatis-Plus？ <a class="header-anchor" href="#为什么-java-版用-mybatis-plus" aria-label="Permalink to &quot;为什么 Java 版用 MyBatis-Plus？&quot;">​</a></h2><p><strong>不是技术选择，是生态选择。</strong></p><ol><li><strong>国内 Java 后端标配</strong>：MyBatis-Plus 在国内 Java 圈的普及率接近 100%，招人成本最低</li><li><strong>微服务架构需要</strong>：8 个服务，每个服务独立数据库，用 ORM 统一 CRUD 写法</li><li><strong>历史惯性</strong>：项目从单体到微服务一路用 MyBatis，没有理由换</li><li><strong><code>${}</code> 是少数场景的逃生口</strong>：MyBatis 设计者没预料到开发者会在用户输入上用它</li></ol><hr><h2 id="对-go-版的建议" tabindex="-1">对 Go 版的建议 <a class="header-anchor" href="#对-go-版的建议" aria-label="Permalink to &quot;对 Go 版的建议&quot;">​</a></h2><h3 id="必需" tabindex="-1">必需 <a class="header-anchor" href="#必需" aria-label="Permalink to &quot;必需&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>建议</th><th>理由</th></tr></thead><tbody><tr><td>迁移工具</td><td>加 <code>golang-migrate</code></td><td>启动时自动跑未执行的 SQL，避免手动操作</td></tr><tr><td>健康检查</td><td>已有</td><td>确认 DB 连通性</td></tr></tbody></table><h3 id="可选-暂不建议" tabindex="-1">可选（暂不建议） <a class="header-anchor" href="#可选-暂不建议" aria-label="Permalink to &quot;可选（暂不建议）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>不建议的理由</th></tr></thead><tbody><tr><td>换 ORM（GORM）</td><td>项目 27K 行，全部手写 SQL，换 ORM 等于重写。收益不大</td></tr><tr><td>加 sqlx</td><td>薄封装，省 <code>rows.Scan</code> 模板代码。可加，但非必需</td></tr><tr><td>加 query builder</td><td>手写 SQL 就是最好的 DSL，多一层抽象多一层认知负担</td></tr></tbody></table><h3 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h3><p><strong>加个迁移工具就够，其他不动。</strong> 手写 SQL + 参数化查询 = 安全 + 清晰，当前架构没有换的理由。</p>',35)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
